#version 300 es
void main() {
  vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}

#version 300 es
precision highp float;
uniform vec2 u_resolution;
out vec4 color;
void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution;
  color = vec4(uv, 0.5, 1.0);
}
